'use strict';
const cloud={revision:null,ready:false,saving:false,pending:null,blocked:false,research:null};
const OUTBOX=KEY+'-cloud-outbox';
function writeOutbox(){if(cloud.pending&&cloud.revision)try{localStorage.setItem(OUTBOX,JSON.stringify({revision:cloud.revision,offers:JSON.parse(cloud.pending)}))}catch{cloudFailure('Não foi possível guardar o rascunho local. Exporte um backup antes de fechar.')}}
function readOutbox(){try{const data=JSON.parse(localStorage.getItem(OUTBOX)||'null');return data&&typeof data.revision==='string'&&Array.isArray(data.offers)&&data.offers.every(validate)?data:null}catch{return null}}
const localPersist=persist;
const localRender=render;
function cloudBadge(text,kind=''){const el=document.querySelector('#cloud-status');if(el){el.textContent=text;el.dataset.kind=kind}}
function cloudFailure(message){cloudBadge('Alterações só neste navegador','error');const box=document.querySelector('#cloud-warning');box.hidden=false;box.querySelector('span').textContent=message;toast(message)}
function cloudResearchMarkup(){const status=cloud.research;return '<strong>Busca na nuvem · integração pendente</strong><br>Horários reservados: 8h, 12h, 16h e 20h (Brasília). A conexão com as lojas foi deixada para depois; nenhuma oferta nova é coletada automaticamente.'+(status?.lastAttemptAt?'<br>Última verificação da configuração: '+esc(new Date(status.lastAttemptAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))+'.':'')}
render=function(){localRender();document.querySelectorAll('.schedule-summary').forEach(el=>el.innerHTML=cloudResearchMarkup());document.querySelectorAll('.simple-footnote').forEach(el=>el.textContent='O envio ao WhatsApp é manual. Seu espaço é sincronizado na nuvem quando conectado.');const note=document.querySelector('#main>.notice:last-child');if(view==='overview'&&note)note.innerHTML='<strong>Você tem a palavra final.</strong> Nenhuma mensagem é enviada automaticamente. Seu espaço fica salvo na nuvem após a confirmação de sincronização.'};
persist=function(){const saved=localPersist();if(cloud.ready){cloud.pending=JSON.stringify(offers);writeOutbox();cloudBadge('Salvando na nuvem…');void flushCloud()}return saved};
async function request(path,options={}){const response=await fetch(path,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...options.headers},cache:'no-store'});let body;try{body=await response.json()}catch{throw Object.assign(new Error('O servidor não respondeu como esperado.'),{status:response.status})}if(!response.ok)throw Object.assign(new Error(body.error||'Falha de sincronização.'),{status:response.status});return body}
async function flushCloud(){if(cloud.saving||cloud.blocked||!cloud.pending||!cloud.ready)return;cloud.saving=true;writeOutbox();const snapshot=cloud.pending;const revision=cloud.revision;cloud.pending=null;try{const result=await request('/api/workspace',{method:'PUT',body:JSON.stringify({revision,offers:JSON.parse(snapshot)})});cloud.revision=result.revision;const stored=readOutbox();if(stored&&stored.revision===revision&&JSON.stringify(stored.offers)===snapshot)localStorage.removeItem(OUTBOX);if(cloud.pending)writeOutbox();cloudBadge('Salvo na nuvem');document.querySelector('#cloud-warning').hidden=true}catch(err){if(!cloud.pending)cloud.pending=snapshot;writeOutbox();cloud.blocked=true;cloudFailure(err.status===409?'Outra sessão alterou seu espaço. Exporte um backup do rascunho local antes de atualizar da nuvem.':err.message);if(err.status===401){cloud.ready=false;showLogin('Sua sessão expirou. Entre novamente; as alterações locais estão preservadas.')}}finally{cloud.saving=false;if(cloud.pending&&!cloud.blocked)void flushCloud()}}
async function loadCloud(discardLocal=false){const result=await request('/api/workspace');if(!Array.isArray(result.offers)||!result.offers.every(validate))throw Error('O espaço na nuvem contém dados inválidos.');const retained=discardLocal?null:readOutbox();if(discardLocal)localStorage.removeItem(OUTBOX);offers=retained?retained.offers:result.offers;cloud.revision=retained?retained.revision:result.revision;cloud.research=result.research;cloud.ready=true;cloud.pending=retained?JSON.stringify(retained.offers):null;cloud.blocked=false;localPersist();render();document.body.classList.remove('cloud-loading');document.querySelector('#cloud-login').hidden=true;document.querySelector('#cloud-warning').hidden=true;cloudBadge(retained?'Recuperando rascunho local…':'Salvo na nuvem');if(retained)await flushCloud()}
function showLogin(message='Entre para acessar suas ofertas e aprovações.'){document.body.classList.add('cloud-loading');document.querySelector('#cloud-login').hidden=false;document.querySelector('#login-feedback').textContent=message;cloudBadge('Entre para sincronizar')}
document.querySelector('#cloud-login-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const button=form.querySelector('button');button.disabled=true;const password=form.elements.password.value;try{await request('/api/session',{method:'POST',body:JSON.stringify({password})});form.reset();await loadCloud()}catch(err){document.querySelector('#login-feedback').textContent=err.message}finally{button.disabled=false}};
document.querySelector('#login-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>4096)throw Error('Arquivo de acesso inválido.');const text=await file.text();const match=text.match(/^Senha: ([A-Za-z0-9_-]{16,300})\s*$/m);if(!match)throw Error('Este não é um arquivo de acesso do Garimpo.');const form=document.querySelector('#cloud-login-form');form.elements.password.value=match[1];form.requestSubmit()}catch(err){document.querySelector('#login-feedback').textContent=err.message}finally{e.target.value=''}};
document.querySelector('#cloud-refresh').onclick=async()=>{if((cloud.pending||cloud.saving)&&!confirm('Atualizar substitui o rascunho local pela versão da nuvem. Exporte um backup antes de continuar. Atualizar agora?'))return;if(cloud.saving){toast('Aguarde o salvamento terminar.');return}try{await loadCloud(true)}catch(err){cloudFailure(err.message)}};
document.querySelector('#cloud-retry').onclick=()=>{cloud.blocked=false;void flushCloud()};
document.querySelector('#cloud-logout').onclick=async()=>{if((cloud.pending||cloud.saving)&&!confirm('Existem alterações sem sincronizar. Exporte um backup antes de sair. Continuar?'))return;try{await request('/api/session',{method:'DELETE'});cloud.ready=false;cloud.revision=null;cloud.pending=null;offers=[];localStorage.removeItem(KEY);localStorage.removeItem(OUTBOX);showLogin('Você saiu do espaço.')}catch(err){cloudFailure(err.message)}};
window.addEventListener('beforeunload',e=>{if(cloud.pending||cloud.saving){e.preventDefault();e.returnValue=''}});
void(async()=>{try{const session=await request('/api/session');if(!session.authenticated){showLogin();return}await loadCloud()}catch(err){showLogin(err.message)}})();
